        "cn": "资本金融市场上的资产投机泡沫，往往因投资者破坏性盲目跟风、随波逐流的羊群效应而急剧膨胀。",
        "jp": "金融市場における投機バブルは、破壊的な羊の群れのような付和雷同性によって増幅されることが頻繁にある。"
