        "cn": "大学校园里充斥着如此高度同质化的意识形态从众从大流氛围，严重挫伤了异见声音的自由表达。",
        "jp": "そのようなイデオロギー的付和雷同がキャンパスを支配していたことは、異論の表明を萎縮させた。"
