    "theme": "Psychologie & Sciences cognitives",
    "type": "nom féminin • soutenu",
    "definition": "Tendance pathologique ou comportementale à différer systématiquement au lendemain l'accomplissement d'une tâche urgente.",
    "traduction_anglais": "procrastination",
    "traduction_chinois": "拖延症 (tuōyánzhèng) / 延宕",
