        "en": "Far from being mere moral laziness, chronic procrastination frequently conceals paralyzing anxiety in the face of failure.",
        "cn": "长期的慢性拖延行为绝非道德层面的单纯懒惰散漫，其潜意识深层往往掩藏着对面临潜在失败的致命瘫痪性焦虑与恐惧。",
        "jp": "単なる道徳的な怠惰であるどころか、慢性的な先延ばしはしばしば失敗に対する麻痺するような不安を覆い隠している。"
