        "cn": "认知心理学家权威指出：拖延症在神经机制上直接关联着个体大脑情绪自我调节能力与前额叶执行控制功能的暂时性失调受损。",
        "jp": "認知心理学者たちは、先延ばしを行動の感情的調節と実行機能の一時的な機能不全に関連づけている。"
