        "en": "That a senior executive succumbed to procrastination when deciding on a strategic investment cost the firm dearly.",
        "cn": "企业高级决策者在拍板定夺关乎集团生死存亡的重大战略投资决策时严重拖延不决，给整家跨国公司造成了无可挽回的惨重经济损失。",
        "jp": "戦略的投資の決断を下す際に上級幹部が先延ばしに屈したことは、企業に巨額の損失をもたらした。"
