        "cn": "为彻底战胜拖延顽疾，临床心理治疗专家大力推荐将宏大复杂的长远目标拆解细化为触手可及、极易执行完成的微型清单单元。",
        "jp": "先延ばしを克服するため、心理療法士たちは野心的な目標を容易に達成可能なマイクロタスクに細分化することを推奨している。"
