      {
        "fr": "Le perfectionnisme inadapté constitue paradoxalement l'un des terreaux les plus fertiles de la procrastination pathologique.",
        "en": "Maladaptive perfectionism paradoxically constitutes one of the most fertile breeding grounds for pathological procrastination.",
        "cn": "病态且不切实际的“完美主义苛求心态”，反常地构成了滋生诱发各种灾难性慢性拖延症最肥沃的心理温床。",
        "jp": "不適応的な完璧主義は、逆説的にも病的な先延ばしの最も肥沃な温床の一つを構成している。"
      },
      {
        "fr": "Mettre en place des rituels de travail rigoureux permet de court-circuiter les pulsions d'évitement et de terrasser la procrastination.",
        "en": "Establishing rigorous work rituals makes it possible to short-circuit avoidance impulses and defeat procrastination.",
        "cn": "通过建立并恪守严格自律的固定工作专注启动仪式，能够有力阻断逃避现实的本能冲动，从而一举彻底斩断拖延恶习的锁链。",
        "jp": "厳格な作業ルーティンを確立することは、回避衝動を短絡させ、先延ばしを打ち負かすことを可能にする。"
      }
