        "cn": "长篇自传体文学的创作倾诉，使得这位女作家在经历长年隐忍的痛苦沉默之后，终于实现了一场洗涤灵魂的彻底解脱宣泄。",
        "jp": "自伝的執筆は、この女性作家が長年の苦痛に満ちた沈黙の後に解放的なカタルシスを達成することを可能にした。"
