        "cn": "传统的丧葬哀悼仪式为社区公众提供了一套程式化规约载体，极其有利于全体族人宣泄抒发共同承担的沉痛哀伤。",
        "jp": "伝統的な服喪の儀礼は、共有された悲嘆のカタルシス的表現に寄与する形式化された枠組みを共同体に提供している。"
